// HasProvider applies the HasEdge predicate on the "provider" edge.
func HasProvider() predicate.KaguyaModelsInfo {
	return predicate.KaguyaModelsInfo(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ProviderTable, ProviderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProviderWith applies the HasEdge predicate on the "provider" edge with a given conditions (other predicates).
func HasProviderWith(preds ...predicate.KaguyaProviderInfo) predicate.KaguyaModelsInfo {
	return predicate.KaguyaModelsInfo(func(s *sql.Selector) {
		step := newProviderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KaguyaModelsInfo) predicate.KaguyaModelsInfo {
	return predicate.KaguyaModelsInfo(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KaguyaModelsInfo) predicate.KaguyaModelsInfo {
	return predicate.KaguyaModelsInfo(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KaguyaModelsInfo) predicate.KaguyaModelsInfo {
	return predicate.KaguyaModelsInfo(sql.NotPredicates(p))
}
